<script setup>
import { onMounted, reactive, ref } from 'vue'
import { Clock3, Plus, RefreshCw, UsersRound, X } from 'lucide-vue-next'
import { createCoupon, getCoupons, getGroupbuyActivities, getStores } from '../services/merchant.js'
const activities=ref([]),coupons=ref([]),stores=ref([]),loading=ref(false),open=ref(false),message=ref('')
const form=reactive({storeId:'',couponName:'',description:'',category:'餐饮',originalPrice:128,salePrice:88,stock:100,limitCount:1,groupPeople:3,groupTimeoutHours:24})
const statusText=s=>({WAITING:'拼单中',SUCCESS:'自然成团',TIMEOUT:'超时失败',FORCE_SUCCESS:'后台强制成功',FORCE_FAIL:'后台强制失败',SUSPEND:'已暂停',CANCEL:'已关闭'}[s]||s)
const statusClass=s=>['SUCCESS','FORCE_SUCCESS'].includes(s)?'success':['TIMEOUT','FORCE_FAIL','CANCEL'].includes(s)?'danger':'warning'
async function load(){loading.value=true;message.value='';try{const [a,c,s]=await Promise.all([getGroupbuyActivities(),getCoupons(),getStores()]);activities.value=a.records||[];coupons.value=c.filter(x=>x.groupEnabled);stores.value=s;if(!form.storeId&&s.length)form.storeId=s[0].storeId}catch(e){message.value=e.message}finally{loading.value=false}}
async function submit(){const now=new Date(),end=new Date(now.getTime()+90*86400000),date=d=>d.toISOString().split('.')[0];try{await createCoupon({...form,storeId:String(form.storeId),coverImageKey:'merchant/groupbuy/default-cover.jpg',groupEnabled:true,groupPeople:Number(form.groupPeople),groupTimeoutHours:Number(form.groupTimeoutHours),originalPrice:Number(form.originalPrice),salePrice:Number(form.salePrice),stock:Number(form.stock),limitCount:Number(form.limitCount),publishTime:date(now),expireTime:date(end),useStartTime:date(now),useEndTime:date(end),reservationRequired:false,refundable:true,holidayAvailable:true,stackable:false,useInstructions:'拼单成功后生成优惠权益，到店出示券码核销。'});open.value=false;await load()}catch(e){message.value=e.message}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><small class="eyebrow">GROUP ORDER CAMPAIGNS</small><h1>拼单活动管理</h1><p>先创建开启拼单的优惠券，经平台审核后用户才能发起和加入拼单。</p></div><div class="actions"><button class="btn" @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button><button class="btn primary" :disabled="!stores.length" @click="open=true"><Plus/>创建拼单优惠</button></div></div><div v-if="message" class="notice danger">{{message}}</div><div class="metric-grid"><article class="metric"><span><UsersRound/></span><div><small>拼单优惠</small><b>{{coupons.length}}</b><em>个</em></div></article><article class="metric"><span><Clock3/></span><div><small>进行中活动</small><b>{{activities.filter(x=>x.activityStatus==='WAITING').length}}</b><em>单</em></div></article></div><section class="panel"><div class="panel-head"><div><h2>用户拼单进度</h2><p>数据来自真实 groupbuy_activity</p></div><UsersRound/></div><div v-if="!activities.length" class="empty compact"><UsersRound/><h2>暂无用户发起的拼单</h2><p>拼单优惠审核通过并在 App 展示后，用户可发起活动。</p></div><div v-else class="table-wrap"><table><thead><tr><th>活动 / 优惠</th><th>门店</th><th>成团进度</th><th>拼单价</th><th>截止时间</th><th>状态</th></tr></thead><tbody><tr v-for="row in activities" :key="row.activityId"><td><b>{{row.couponName}}</b><small>ID {{row.activityId}}</small></td><td>{{row.storeName||'—'}}</td><td>{{row.currentPeople}} / {{row.targetPeople}}</td><td><b class="price">¥{{row.groupPrice}}</b></td><td>{{row.expireAt}}</td><td><span class="tag" :class="statusClass(row.activityStatus)">{{statusText(row.activityStatus)}}</span></td></tr></tbody></table></div></section><div v-if="open" class="modal-mask" @click.self="open=false"><form class="modal wide" @submit.prevent="submit"><div class="modal-head"><div><h2>创建拼单优惠</h2><p>创建后进入平台审核，不会直接上线。</p></div><button type="button" class="plain-icon" @click="open=false"><X/></button></div><div class="form-grid"><label><span>适用门店</span><select v-model="form.storeId" required><option v-for="s in stores" :key="s.storeId" :value="s.storeId">{{s.storeName}}</option></select></label><label><span>分类</span><select v-model="form.category"><option>餐饮</option><option>酒店</option><option>景区</option><option>汽车服务</option><option>露营</option></select></label><label class="full"><span>优惠名称</span><input v-model="form.couponName" required></label><label class="full"><span>优惠描述</span><textarea v-model="form.description" required></textarea></label><label><span>原价</span><input v-model="form.originalPrice" type="number" min="0.01" step="0.01"></label><label><span>拼单价</span><input v-model="form.salePrice" type="number" min="0.01" step="0.01"></label><label><span>成团人数</span><input v-model="form.groupPeople" type="number" min="2"></label><label><span>拼单有效时间（小时）</span><input v-model="form.groupTimeoutHours" type="number" min="1"></label><label><span>库存</span><input v-model="form.stock" type="number" min="1"></label><label><span>每人限购</span><input v-model="form.limitCount" type="number" min="1"></label></div><div class="modal-foot"><button type="button" class="btn" @click="open=false">取消</button><button class="btn primary">提交平台审核</button></div></form></div></div></template>
